public class SimulacionFisica extends Trabajo {

    // Nuevo atributo de la clase:
    protected int resolucion;

    // Constructor vacío
    public SimulacionFisica() {
		//Trae los atributos de arriba
        super();
        resolucion = 0;
    }


    // Constructor default completo

    public SimulacionFisica(String codigo, String estudio, String nombre, float horasEstimadas, boolean diurno, int resolucion) {
		//Trae los datos de la clase Trabajo
        super(codigo, estudio, nombre, horasEstimadas, diurno);
		//Define el nuevo
        this.resolucion = resolucion;
    }


    // Set y get, nuevamente.

    public void setResolucion(int newResolucion) {
        resolucion = newResolucion;
    }

    public int getResolucion() {
        return resolucion;
    }


    // Nuevo costo

    @Override
    public float calcularCosto() {
		//Defini está como la tarifa base. Por que asi lo quise.
		//Btw, terminan en f para que tengan solo esa cantidad de decimales fijos.
        float tarifaBase = 40.0f;

        // Horas estimadas * 22
        float costoHoras = horasEstimadas * 22.0f;

        // Tarifa + horas + GPU
        return tarifaBase + costoHoras + 65.0f;
    }


    // Tiempo de entrega depende, asi que nuevo Override
    @Override
    public int tiempoEntrega() {

        return 18;
    }


    // Definir nueva cantidad de intentos

    @Override
    public int maxIntentos() {

        return 1;
    }


    // Ahora el override tiene sentido, por que solo este tiene que verificar si tiene GPU o no.
	//Este es el único override
    @Override
    public boolean compatNodo(Nodo nodo) {

        return nodo.getGpu();
    }

//Nueva categoría.

    @Override
    public String getCategoria() {

        return "Simulacion Fisica";
    }
}
